package br.com.trama.controller;
import br.com.trama.dto.ProdutoRequest; import br.com.trama.dto.ProdutoResponse; import br.com.trama.model.*; import br.com.trama.repository.*; import br.com.trama.error.ResourceNotFoundException; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/produtos") @Tag(name="Produtos",description="Catálogo de produtos artesanais") public class ProdutoController { private final ProdutoRepository produtos; private final ArtesaoRepository artesaos; public ProdutoController(ProdutoRepository p,ArtesaoRepository a){produtos=p;artesaos=a;}
 @PostMapping @PreAuthorize("hasAnyRole('ADMIN','ARTESAO')") @Operation(summary="Cadastrar produto",description="Vincula o produto a um artesão existente.") public ResponseEntity<ProdutoResponse> criar(@Valid @RequestBody ProdutoRequest dto){Artesao a=artesaos.findById(dto.idArtesao()).orElseThrow(()->new ResourceNotFoundException("Artesão não encontrado.")); Produto p=new Produto();p.setNome(dto.nome());p.setDescricao(dto.descricao());p.setPreco(dto.preco());p.setArtesao(a);Produto salvo=produtos.save(p);URI uri=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(salvo.getId()).toUri();return ResponseEntity.created(uri).body(toResponse(salvo));}
 @GetMapping @Operation(summary="Listar produtos") public List<ProdutoResponse> listar(){return produtos.findAll().stream().map(this::toResponse).toList();}
 @GetMapping("/{id}") @Operation(summary="Buscar produto por ID") public ProdutoResponse buscar(@PathVariable Long id){Produto p=produtos.findById(id).orElseThrow(()->new ResourceNotFoundException("Produto não encontrado."));return toResponse(p);}
 private ProdutoResponse toResponse(Produto p){return new ProdutoResponse(p.getId(),p.getNome(),p.getDescricao(),p.getPreco(),p.getArtesao().getId());}
}
